(15, 207, 2, 277, '[{\"type\": \"dodge\", \"value\": 8, \"locked\": false, \"is_percent\": false}, {\"type\": \"hp_max\", \"value\": 115, \"locked\": false, \"is_percent\": false}, {\"type\": \"attack\", \"value\": 20, \"locked\": true, \"is_percent\": false}]', NULL, 1, '2026-07-20 08:21:24', '2026-07-20 08:21:30'),
