INSERT INTO `locations` (`id`, `map_id`, `dungeon_id`, `name`, `description`, `image`, `north`, `south`, `east`, `west`, `up`, `down`, `count_monster`, `percent_respawn_monster`, `time_not_attack`, `is_locked`, `last_respawn_monster_at`, `created_at`, `updated_at`) VALUES
(1, 1, NULL, 'Южные ворота', 'Вы стоите на широкой дороге, продолжающейся на север и на юг. К югу от вас находится лес, а на севере расположены массивные ворота города Тэйл. Над ними возвышается сторожевая башня, сложенная из светлого камня. С двух сторон к ней прилегает высокая оборонительная стена, которой обнесен весь город. Сквозь арку ворот видна городская площадь и неспешно прогуливающиеся по ней люди. Здесь всегда царит мир и спокойствие, а добродушные жители рады новым гостям.', NULL, 2, 101, 52, 53, NULL, NULL, 2, 50, 10, 0, '2026-08-10 14:46:04', '2024-09-11 10:40:56', '2026-08-10 14:46:04'),
(2, 1, NULL, 'Улица центральная', 'Вы идете по переулку, соединяющему Главную площадь города с улицей Волшебного алтаря. По сторонам расположены каменные стены торговых зданий, на которых нет ни единого окна.', NULL, 3, 1, 94, 54, NULL, NULL, 5, 70, 10, 0, '2026-07-30 11:28:42', '2024-09-11 10:40:56', '2026-07-30 11:28:42'),
(3, 1, NULL, 'Улица центральная', 'Вы находитесь в просторном помещении, заставленном деревянными ящиками и сундуками. В северной стене виднеется проход, ведущий в подсобные помещения, входить в которые могут только работники хранилища. За высоким прилавком стоит кладовщица. У нее вы можете оставить вещи на хранение или же забрать их.', NULL, 4, 2, NULL, NULL, NULL, NULL, 0, 0, 0, 0, NULL, '2024-09-11 10:40:56', '2024-09-11 10:40:56'),
(4, 1, NULL, 'Улица центральная', 'Вы находитесь в большом хорошо освещенном зале. Вверх ведет спиральная резная лестница работы искусных мастеров. К югу от вас расположена двойная деревянная дверь, ведущая на улицу. В центре зала возвышается волшебный алтарь, излучающий слабое свечение. В нем заключена великая сила', NULL, 5, 3, NULL, NULL, NULL, NULL, 0, 0, 0, 0, NULL, '2024-09-11 10:40:56', '2024-09-11 10:40:56'),
(5, 1, NULL, 'Центральная площадь', NULL, NULL, 6, 4, 11, 10, NULL, NULL, 0, 0, 0, 0, NULL, NULL, NULL),
(6, 1, NULL, 'Городское сердце', 'Главная площадь города, где сходятся шумные улицы, караульные маршруты и дороги путников. В центре площади бьет целительный фонтан, рядом дежурит городская стража, а неподалеку виднеется спуск в подземелье. Здесь принимают важные решения, встречают новичков и собираются перед тем, как отправиться за городские стены или вниз, к темным ходам под городом.', '/storage/locations/R6KhhpK44j8v5aEDpshXkyoTpeIfM1295asoJops.png', NULL, 5, NULL, NULL, NULL, 819, 0, 0, 0, 0, NULL, NULL, '2026-07-30 08:27:03'),
