(396, 2, NULL, 'Опушка Глухого Леса', 'Деревья здесь стоят плотнее, свет с тракта гаснет за спиной. Первые шаги в настоящую чащу.', NULL, NULL, NULL, 397, 106, NULL, NULL, 1, 50, 15, 0, '2026-08-10 15:17:17', NULL, '2026-08-10 15:17:17'),
(397, 2, NULL, 'Заросшая Прогалина', 'Небольшой просвет между деревьями, заросший высокой сухой травой и кустарником.', NULL, 399, NULL, NULL, 396, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(398, 2, NULL, 'Тупик у Валежника', 'Путь обрывается грудой поваленных стволов, поросших мхом; дальше не пройти.', NULL, NULL, NULL, 399, NULL, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(399, 2, NULL, 'Развилка Мохового Ручья', 'Едва слышно журчит подземный ручеёк под ковром мха; тропы расходятся в стороны.', NULL, NULL, 397, 400, 398, NULL, NULL, 1, 50, 15, 0, '2026-08-10 15:16:59', NULL, '2026-08-10 15:16:59'),
(400, 2, NULL, 'Тропа Кабаньих Нор', 'Земля здесь изрыта многочисленными норами и бороздами — тут любят рыться дикие кабаны.', NULL, NULL, NULL, 401, 399, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(401, 2, NULL, 'Заросли Терновника', 'Густые колючие кусты цепляются за одежду, замедляя каждый шаг.', NULL, NULL, NULL, 402, 400, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(402, 2, NULL, 'Полог Старых Сосен', 'Высокие сосны смыкают кроны так плотно, что днём здесь царят сумерки.', NULL, NULL, 403, NULL, 401, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(403, 2, NULL, 'Овраг с Сухим Руслом', 'Неглубокий овраг, некогда бывший руслом реки, пересекает тропу.', NULL, 402, 404, NULL, NULL, NULL, NULL, 1, 50, 15, 0, '2026-08-10 15:16:19', NULL, '2026-08-10 15:16:19'),
(404, 2, NULL, 'Перекрёсток Троп', 'Здесь пересекаются несколько звериных троп; одна уводит на восток, к более опасным местам.', NULL, 403, NULL, 450, 405, NULL, NULL, 1, 50, 15, 0, '2026-08-10 16:31:33', NULL, '2026-08-10 16:31:33'),
(405, 2, NULL, 'Поляна Обломанных Веток', 'Земля усыпана обломанными ветвями — будто здесь недавно прошло что-то крупное и сильное.', NULL, NULL, 406, 404, NULL, NULL, NULL, 1, 50, 15, 0, '2026-08-10 15:12:28', NULL, '2026-08-10 15:12:28'),
(406, 2, NULL, 'Развилка у Гнилого Пня', 'Огромный трухлявый пень, выеденный изнутри, отмечает очередное разветвление пути.', NULL, 405, 419, NULL, 407, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(407, 2, NULL, 'Тропа Паутины', 'Между деревьями то и дело провисает старая, покинутая паутина размером с человеческий рост.', NULL, NULL, NULL, 406, 408, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(408, 2, NULL, 'Заболоченный Участок', 'Почва здесь мягкая и влажная, шаги хлюпают, воздух пахнет гнилью.', NULL, NULL, 409, 407, NULL, NULL, NULL, 1, 50, 15, 0, '2026-08-11 09:16:48', NULL, '2026-08-11 09:16:48'),
(409, 2, NULL, 'Просека Молодой Поросли', 'Здесь когда-то упало старое дерево, и на его месте пробилась молодая, но частая поросль.', NULL, 408, 410, NULL, NULL, NULL, NULL, 1, 50, 15, 0, '2026-08-11 14:15:59', NULL, '2026-08-11 14:15:59'),
(410, 2, NULL, 'Скопление Валунов', 'Несколько замшелых валунов, будто нарочно сложенных в круг, преграждают путь.', NULL, 409, NULL, NULL, 411, NULL, NULL, 1, 50, 15, 0, '2026-08-10 15:11:39', NULL, '2026-08-10 15:11:39'),
(411, 2, NULL, 'Тропа Долгой Тени', 'Даже в полдень эта часть леса тонет в густой тени высоких крон.', NULL, 412, NULL, 410, NULL, NULL, NULL, 1, 50, 15, 0, '2026-08-11 09:17:11', NULL, '2026-08-11 09:17:11'),
(412, 2, NULL, 'Поляна Сухих Листьев', 'Кольцо мёртвых деревьев без единого зелёного листа посреди живого леса.', NULL, 413, 411, NULL, NULL, NULL, NULL, 1, 50, 15, 0, '2026-08-11 14:15:50', NULL, '2026-08-11 14:15:50'),
(413, 2, NULL, 'Разлом в Земле', 'Узкая расщелина рассекает тропу, откуда тянет прохладным сырым воздухом.', NULL, 414, 412, NULL, NULL, NULL, NULL, 1, 50, 15, 0, '2026-08-11 09:28:18', NULL, '2026-08-11 09:28:18'),
(414, 2, NULL, 'Заросший Указатель', 'Полусгнивший деревянный указатель, буквы на котором давно стёрлись от времени.', NULL, NULL, 413, 415, NULL, NULL, NULL, 1, 50, 15, 0, '2026-08-11 09:28:26', NULL, '2026-08-11 09:28:26'),
(415, 2, NULL, 'Чаща Кривых Стволов', 'Деревья здесь растут неестественно изогнутыми, будто что-то годами гнуло их к земле.', NULL, NULL, NULL, 416, 414, NULL, NULL, 1, 50, 15, 0, '2026-08-11 14:15:42', NULL, '2026-08-11 14:15:42'),
(416, 2, NULL, 'Тропа у Ручья', 'Узкий ручей пересекает путь, его вода на удивление холодная даже летом.', NULL, 417, NULL, NULL, 415, NULL, NULL, 1, 50, 15, 0, '2026-08-11 14:15:33', NULL, '2026-08-11 14:15:33'),
(417, 2, NULL, 'Последний Просвет Чащи', 'Деревья редеют, а впереди слышен странный, тянущий за душу гул из-под земли.', NULL, NULL, 416, 418, NULL, NULL, NULL, 1, 50, 15, 0, '2026-08-11 09:28:40', NULL, '2026-08-11 09:28:40'),
(418, 2, NULL, 'Вход под корнями', 'Огромное дерево вывернуло здесь землю, обнажив узкий провал меж своих корней. Из темноты тянет сыростью и запахом старой земли — вниз ведёт спуск в Забытый Курган.', '/storage/locations/EnBFz5PIbr7hfmMSkrt9OWZrDINM4yJ7hF9U7DOx.png', NULL, NULL, NULL, 417, NULL, 883, 1, 50, 15, 0, '2026-08-11 14:15:28', NULL, '2026-08-11 14:15:28'),
(419, 2, NULL, 'Развилка у Мёртвого Дуба', 'Расколотый молнией дуб-исполин отмечает ещё одно разветвление тропы.', NULL, 406, 420, NULL, NULL, NULL, NULL, 1, 50, 15, 0, '2026-08-11 14:16:12', NULL, '2026-08-11 14:16:12'),
(420, 2, NULL, 'Перепутье Глухих Троп', 'Здесь пути расходятся сразу в три стороны, ни один не выглядит безопаснее другого.', NULL, 419, 427, NULL, 422, NULL, NULL, 1, 50, 15, 0, '2026-08-10 15:03:37', NULL, '2026-08-10 15:06:53'),
(421, 2, NULL, 'Тупик Заросшей Норы', 'Крупная звериная нора у корней дерева; сама тропа обрывается здесь.', NULL, NULL, 422, NULL, NULL, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(422, 2, NULL, 'Поляна Плетёных Ветвей', 'Ветви соседних деревьев переплелись так плотно, что образовали подобие свода.', NULL, 421, 423, 420, NULL, NULL, NULL, 1, 50, 15, 0, '2026-08-11 14:16:18', NULL, '2026-08-11 14:16:18'),
(423, 2, NULL, 'Заросли Дикой Ежевики', 'Спелая ежевика густо оплетает всё вокруг, привлекая и зверьё, и хищников.', NULL, 422, NULL, NULL, 424, NULL, NULL, 1, 50, 15, 0, '2026-08-11 14:16:21', NULL, '2026-08-11 14:16:21'),
(424, 2, NULL, 'Тропа Примятой Травы', 'Высокая трава здесь примята широкой полосой — недавно прошло что-то тяжёлое.', NULL, NULL, NULL, 423, 425, NULL, NULL, 1, 50, 15, 0, '2026-08-11 14:16:26', NULL, '2026-08-11 14:16:26'),
(425, 2, NULL, 'Овраг с Костями', 'На дне неглубокого оврага белеют обглоданные кости — здесь местные хищники не первый год оставляют объедки своей добычи.', NULL, NULL, 426, 424, NULL, NULL, NULL, 1, 50, 15, 0, '2026-08-10 15:26:30', NULL, '2026-08-10 15:26:30'),
(426, 2, NULL, 'Редколесье у Опушки', 'Деревья здесь заметно реже, а под ногами всё чаще попадаются проплешины голой земли — лес постепенно уступает место чему-то иному.', NULL, 425, NULL, NULL, 112, NULL, NULL, 1, 50, 15, 0, '2026-08-10 15:26:17', NULL, '2026-08-10 15:26:17'),
(427, 2, NULL, 'Развилка у Каменной Плиты', 'Плоский замшелый камень, вросший в землю, отмечает старое разветвление пути.', NULL, 420, 428, NULL, NULL, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(428, 2, NULL, 'Тропа Сломанных Копий', 'Несколько истлевших обломков деревянных копий воткнуты в землю вдоль тропы.', NULL, 427, NULL, 429, NULL, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(429, 2, NULL, 'Прогалина Тихого Шёпота', 'Ветер здесь странно шелестит в листве, будто лес что-то тихо нашёптывает.', NULL, NULL, 430, NULL, 428, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(430, 2, NULL, 'Заросли Мать-и-мачехи', 'Влажная низина, густо поросшая широколистной травой.', NULL, 429, NULL, 431, NULL, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(431, 2, NULL, 'Тропа Каменной Гряды', 'Ряд крупных валунов тянется вдоль пути, будто древняя стена.', NULL, NULL, NULL, 432, 430, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(432, 2, NULL, 'Перекрёсток Четырёх Троп', 'Крупный перекрёсток, откуда тропы расходятся во все стороны леса.', NULL, 433, NULL, 439, 431, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(433, 2, NULL, 'Тупик у Расколотого Камня', 'Огромный камень, расколотый пополам ударом неведомой силы.', NULL, NULL, 432, NULL, 434, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(434, 2, NULL, 'Поляна Опавшей Хвои', 'Мягкий толстый ковёр из опавшей хвои устилает всю поляну.', NULL, 436, NULL, 433, NULL, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(435, 2, NULL, 'Тупик Густых Зарослей', 'Кусты и подлесок здесь настолько густые, что дальше идти невозможно.', NULL, NULL, NULL, 436, NULL, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(436, 2, NULL, 'Развилка у Муравейника', 'Огромный муравейник высотой в человеческий рост возвышается у тропы.', NULL, NULL, 434, 437, 435, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(437, 2, NULL, 'Тропа Гнутых Ветвей', 'Низко нависающие ветви заставляют путников пригибаться на каждом шагу.', NULL, NULL, NULL, 438, 436, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(438, 2, NULL, 'Тупик у Высохшего Дерева', 'Мёртвое высохшее дерево торчит посреди тропы, дальше пути нет.', NULL, NULL, NULL, NULL, 437, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(439, 2, NULL, 'Развилка у Медвежьей Тропы', 'Глубокие когтистые следы на коре деревьев выдают частые визиты крупного зверя.', NULL, NULL, NULL, 440, 432, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(440, 2, NULL, 'Прогалина Битого Валежника', 'Множество поваленных, будто переломанных пополам, стволов деревьев.', NULL, NULL, NULL, 441, 439, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(441, 2, NULL, 'Тропа Сырого Мха', 'Толстый влажный мох покрывает всё вокруг, приглушая звук шагов.', NULL, NULL, NULL, 442, 440, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(442, 2, NULL, 'Развилка у Старой Ловушки', 'Останки самодельного капкана, давно проржавевшего, лежат у обочины тропы.', NULL, 443, NULL, NULL, 441, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(443, 2, NULL, 'Поляна Бледных Грибов', 'Множество бледных, будто светящихся в сумерках, грибов растёт кольцом.', NULL, 444, 442, NULL, NULL, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(444, 2, NULL, 'Тропа Скрипучих Стволов', 'Стволы деревьев здесь неестественно скрипят даже без ветра.', NULL, NULL, 443, NULL, 445, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(445, 2, NULL, 'Развилка у Расщеплённого Пня', 'Пень, расколотый будто топором великана, лежит на перекрёстке троп.', NULL, NULL, 446, 444, NULL, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(446, 2, NULL, 'Тропа Густого Подлеска', 'Подлесок здесь такой густой, что видимость падает до нескольких шагов.', NULL, 445, NULL, NULL, 447, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(447, 2, NULL, 'Перекрёсток Забытых Троп', 'Ещё один крупный перекрёсток, заросший так, будто им давно не пользовались.', NULL, 449, NULL, 446, 448, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(448, 2, NULL, 'Тупик Замшелых Камней', 'Груда замшелых камней преграждает путь дальше.', NULL, NULL, NULL, 447, NULL, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(449, 2, NULL, 'Дальний Тупик Чащи', 'Самый дальний, глухой уголок леса на этом участке — дальше только непроходимая чаща.', NULL, NULL, 447, NULL, NULL, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 15:06:53'),
(450, 2, NULL, 'Порог Древней Чащи', 'Деревья здесь старше самого города — их стволы в три обхвата, а кроны скрывают небо целиком. Начинается самая опасная часть леса.', NULL, NULL, 451, NULL, 404, NULL, NULL, 1, 50, 15, 0, '2026-08-10 16:31:38', NULL, '2026-08-10 18:01:22'),
(451, 2, NULL, 'Тропа Вековых Корней', 'Могучие корни вспучили землю так, что тропа превратилась в череду ям и горбов.', NULL, 450, NULL, 452, NULL, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(452, 2, NULL, 'Поляна Мёртвой Тишины', 'Ни птицы, ни насекомого — тишина здесь плотная, будто сам лес затаил дыхание.', NULL, NULL, NULL, 453, 451, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(453, 2, NULL, 'Разлом Старого Великана', 'Расколотый надвое исполинский ствол лежит поперёк тропы — что свалило его, неизвестно.', NULL, NULL, NULL, 454, 452, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(454, 2, NULL, 'Тропа Глубоких Теней', 'Кроны здесь смыкаются так плотно, что даже в полдень царят вечерние сумерки.', NULL, NULL, 455, NULL, 453, NULL, NULL, 1, 50, 15, 0, '2026-08-10 16:31:50', NULL, '2026-08-10 18:01:22'),
(455, 2, NULL, 'Логово в Корнях', 'Между исполинскими корнями зияет тёмный провал — судя по следам, чьё-то логово.', NULL, 454, NULL, NULL, 456, NULL, NULL, 1, 50, 15, 0, '2026-08-11 09:15:55', NULL, '2026-08-11 09:15:55'),
(456, 2, NULL, 'Поляна Побелевших Стволов', 'Кольцо мёртвых, побелевших деревьев посреди живого леса — земля здесь давно бесплодна.', NULL, NULL, NULL, 455, 457, NULL, NULL, 1, 50, 15, 0, '2026-08-11 09:15:51', NULL, '2026-08-11 09:15:51'),
(457, 2, NULL, 'Тропа Глубоких Царапин', 'Глубокие борозды когтей исполосовали кору ближайших деревьев на высоте человеческого роста.', NULL, NULL, NULL, 456, 458, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(458, 2, NULL, 'Перекрёсток Древних Троп', 'Несколько троп, протоптанных явно не людьми, сходятся здесь в одну точку.', NULL, NULL, NULL, 457, 460, NULL, NULL, 1, 50, 15, 0, '2026-08-11 09:15:42', NULL, '2026-08-11 09:15:42'),
(459, 2, NULL, 'Древо Небесного Света', 'Посреди сумрачной чащи неожиданно светло — здесь растёт исполинское дерево, чья листва мягко мерцает, будто впитала в себя частицу небес. Под его кроной царит тишина без страха: даже лесное зверьё обходит это место стороной, а раны затягиваются здесь быстрее, чем где-либо в лесу.', '/storage/locations/FBLUQixgklzRAKXOlU9DwWq63dHma6vgs0zSg3I6.png', NULL, 460, NULL, NULL, NULL, NULL, 1, 50, 15, 0, '2026-08-10 16:35:37', NULL, '2026-08-10 16:35:37'),
(460, 2, NULL, 'Опушка у Светлого Древа', 'Немного в стороне брезжит непривычный тёплый свет — там, где растёт святое дерево. Здесь же снова властвует тьма чащи.', NULL, 459, 461, 458, NULL, NULL, NULL, 1, 50, 15, 0, '2026-08-10 18:01:42', NULL, '2026-08-10 18:01:42'),
(461, 2, NULL, 'Тропа Треснувшей Земли', 'Земля вдоль тропы покрыта сетью глубоких трещин, будто высохла изнутри много лет назад.', NULL, 460, NULL, 462, NULL, NULL, NULL, 1, 50, 15, 0, '2026-08-10 17:59:12', NULL, '2026-08-10 18:01:22'),
(462, 2, NULL, 'Заросли Чёрного Терновника', 'Шипы этого терновника чернее обычных и словно тянутся навстречу движению.', NULL, NULL, NULL, 463, 461, NULL, NULL, 1, 50, 15, 0, '2026-08-11 06:17:20', NULL, '2026-08-11 06:17:20'),
(463, 2, NULL, 'Поляна Каменных Клыков', 'Острые обломки камня торчат из земли рядами, будто клыки исполинского зверя.', NULL, NULL, NULL, 464, 462, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(464, 2, NULL, 'Тропа Гулкого Эха', 'Каждый звук здесь отражается странным долгим эхом, будто лес отвечает путнику.', NULL, NULL, NULL, 465, 463, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(465, 2, NULL, 'Просека Сломанных Копий', 'Десятки полусгнивших древков воткнуты в землю — здесь когда-то была стычка, и не одна.', NULL, NULL, NULL, 466, 464, NULL, NULL, 1, 50, 15, 0, '2026-08-11 06:17:11', NULL, '2026-08-11 06:17:11'),
(466, 2, NULL, 'Овраг Гниющей Листвы', 'Толстый слой прелой листвы копился здесь десятилетиями, источая тяжёлый смрад.', NULL, NULL, NULL, 467, 465, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(467, 2, NULL, 'Тропа Кривых Теней', 'Тени деревьев ложатся на землю неправильно, не там, где должно быть солнце.', NULL, NULL, NULL, 468, 466, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(468, 2, NULL, 'Поляна Обугленных Пней', 'Кольцо обугленных пней — след давнего пожара, который лес так и не залечил.', NULL, NULL, 469, NULL, 467, NULL, NULL, 1, 50, 15, 0, '2026-08-11 06:16:59', NULL, '2026-08-11 06:16:59'),
(469, 2, NULL, 'Развилка у Мёртвой Ивы', 'Сухая ива без единого листа склонилась над развилкой, будто указывая путь.', NULL, 468, NULL, 470, NULL, NULL, NULL, 1, 50, 15, 0, '2026-08-11 06:16:12', NULL, '2026-08-11 06:16:12'),
(470, 2, NULL, 'Тропа Тяжёлого Воздуха', 'Воздух здесь густой и вязкий, дышать тяжелее с каждым шагом вглубь.', NULL, NULL, NULL, 471, 469, NULL, NULL, 1, 50, 15, 0, '2026-08-11 06:16:04', NULL, '2026-08-11 06:16:04'),
(471, 2, NULL, 'Заросли Ядовитого Плюща', 'Плющ с тёмно-багровыми листьями оплетает стволы деревьев, источая едкий запах.', NULL, NULL, NULL, 472, 470, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(472, 2, NULL, 'Перекрёсток Старой Крови', 'Тёмные пятна, въевшиеся в кору соседних деревьев, слишком похожи на засохшую кровь.', NULL, 473, 506, NULL, 471, NULL, NULL, 1, 50, 15, 0, '2026-08-10 19:43:01', NULL, '2026-08-10 19:43:01'),
(473, 2, NULL, 'Тропа Обломанных Клыков', 'Обломки крупных звериных клыков валяются среди листвы — здесь недавно кто-то проиграл схватку.', NULL, 474, 472, NULL, NULL, NULL, NULL, 1, 50, 15, 0, '2026-08-11 06:15:28', NULL, '2026-08-11 06:15:28'),
(474, 2, NULL, 'Развилка Четырёх Ветров', 'Крупный перекрёсток троп, где ветер дует одновременно с разных сторон, путая направление.', NULL, 483, 473, 475, 505, NULL, NULL, 1, 50, 15, 0, '2026-08-10 18:03:29', NULL, '2026-08-10 18:03:29'),
(475, 2, NULL, 'Поляна Битого Камня', 'Осколки крупного валуна разбросаны широким кругом — что-то расколотило его одним ударом.', NULL, NULL, NULL, 476, 474, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(476, 2, NULL, 'Тупик у Вывернутых Корней', 'Вывернутые из земли корни исполинского дерева перегораживают путь дальше.', NULL, 477, NULL, NULL, 475, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(477, 2, NULL, 'Тропа Долгого Молчания', 'Ни шороха, ни треска ветки — лес здесь будто вымер, и от этого только тревожнее.', NULL, 478, 476, NULL, NULL, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(478, 2, NULL, 'Заросли Кровавых Ягод', 'Кусты усыпаны тёмно-красными ягодами, слишком яркими, чтобы быть съедобными.', NULL, NULL, 477, NULL, 481, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(479, 2, NULL, 'Тупик у Расколотого Валуна', 'Огромный валун, расколотый пополам неведомой силой, преграждает путь окончательно.', NULL, NULL, NULL, NULL, 480, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(480, 2, NULL, 'Поляна Спутанных Ветвей', 'Ветви окрестных деревьев переплелись в плотный, почти непроходимый свод.', NULL, NULL, 481, 479, NULL, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(481, 2, NULL, 'Перекрёсток Тихого Ужаса', 'Разум подсказывает уйти отсюда как можно быстрее, хотя ничего явно опасного не видно.', NULL, 480, 482, 478, NULL, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(482, 2, NULL, 'Тупик у Древнего Алтаря', 'Полуразрушенный каменный алтарь, поросший мхом, — единственное, что осталось от забытого ритуала.', NULL, 481, NULL, NULL, NULL, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(483, 2, NULL, 'Тропа Хрустящих Костей', 'Под ногами то и дело хрустят мелкие кости, скрытые под ковром палой листвы.', NULL, 484, 474, NULL, NULL, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(484, 2, NULL, 'Поляна Бледного Мха', 'Мох здесь неестественно бледный, почти белый, и мягко фосфоресцирует в сумерках.', NULL, 485, 483, NULL, NULL, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(485, 2, NULL, 'Тропа Дурного Предчувствия', 'Каждый шаг здесь даётся с трудом — тело само противится идти дальше.', NULL, NULL, 484, NULL, 486, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(486, 2, NULL, 'Развилка у Сломанного Копья', 'Древнее ржавое копьё, воткнутое в землю по самое древко, отмечает разветвление тропы.', NULL, 487, NULL, 485, NULL, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(487, 2, NULL, 'Заросли Шипастой Лозы', 'Длинные плети колючей лозы свисают с деревьев, цепляясь за всё живое.', NULL, NULL, 486, NULL, 488, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(488, 2, NULL, 'Тропа Гнилых Пней', 'Ряд трухлявых пней, изъеденных изнутри, тянется вдоль всей тропы.', NULL, NULL, NULL, 487, 489, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(489, 2, NULL, 'Поляна Холодного Пепла', 'Пепел устилает землю тонким слоем, хотя огня здесь не разводили давным-давно.', NULL, NULL, NULL, 488, 490, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(490, 2, NULL, 'Тропа Разодранной Коры', 'Кора деревьев вдоль пути содрана широкими полосами, будто когтями исполинского зверя.', NULL, NULL, NULL, 489, 491, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(491, 2, NULL, 'Заросли Чёрного Мха', 'Чёрный мох покрывает всё вокруг плотным ковром, приглушая каждый шаг до полной тишины.', NULL, NULL, NULL, 490, 492, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(492, 2, NULL, 'Тропа Треснувших Валунов', 'Крупные камни вдоль тропы покрыты сетью трещин, будто их что-то годами сдавливало.', NULL, NULL, NULL, 491, 493, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(493, 2, NULL, 'Развилка у Старого Черепа', 'Огромный, поросший мхом череп неизвестного зверя лежит у развилки троп.', NULL, NULL, 494, 492, NULL, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(494, 2, NULL, 'Тропа Липкой Паутины', 'Густая, липкая паутина затягивает промежутки между деревьями плотнее обычного.', NULL, 493, NULL, NULL, 495, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(495, 2, NULL, 'Поляна Гнутых Стволов', 'Стволы деревьев здесь изогнуты дугой к земле, будто их придавило нечто огромное.', NULL, NULL, 496, 494, NULL, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(496, 2, NULL, 'Тропа Затаившегося Взгляда', 'Чувство, будто за каждым шагом наблюдают из тени, не отпускает ни на миг.', NULL, 495, NULL, 497, NULL, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(497, 2, NULL, 'Заросли Мёртвых Лоз', 'Высохшие лозы плотно опутывают стволы, забирая последние соки из старых деревьев.', NULL, NULL, NULL, 498, 496, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(498, 2, NULL, 'Тропа Каменного Излома', 'Земля вспучена неровными каменными грядами, будто лес растёт прямо на изломе скалы.', NULL, NULL, NULL, 499, 497, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(499, 2, NULL, 'Поляна Забытого Костра', 'Старое кострище, давно остывшее, — единственный след людей на много шагов вокруг.', NULL, NULL, NULL, 500, 498, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(500, 2, NULL, 'Тропа Свинцовой Тишины', 'Тишина здесь давит почти физически, будто сам воздух стал плотнее.', NULL, NULL, 501, NULL, 499, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(501, 2, NULL, 'Развилка у Ржавого Клинка', 'Сломанный, изъеденный ржавчиной клинок торчит из земли на развилке троп.', NULL, 500, NULL, 502, NULL, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(502, 2, NULL, 'Заросли Кривых Игл', 'Хвоя окрестных деревьев неестественно длинная и острая, будто настоящие иглы.', NULL, NULL, NULL, 503, 501, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(503, 2, NULL, 'Тропа Сырого Мрака', 'Даже днём здесь темно, как в глубоких сумерках, а воздух пропитан сыростью.', NULL, NULL, NULL, 504, 502, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(504, 2, NULL, 'Поляна Расколотых Костей', 'Крупные кости, расколотые пополам явно не для еды, разбросаны по всей поляне.', NULL, NULL, 505, NULL, 503, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(505, 2, NULL, 'Перекрёсток Последних Троп', 'Здесь сходятся последние тропы этой части леса — дальше начинается настоящая глушь.', NULL, 504, NULL, 474, NULL, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
(506, 2, NULL, 'Тропа Погасшего Света', 'Даже скудный свет, пробивающийся сквозь кроны, здесь будто гаснет на полпути к земле.', NULL, 472, 507, NULL, NULL, NULL, NULL, 1, 50, 15, 0, '2026-08-10 18:02:52', NULL, '2026-08-10 18:02:52'),
(507, 2, NULL, 'Заросли Могильного Плюща', 'Тёмный плющ оплетает деревья так плотно, что напоминает саван.', NULL, 506, NULL, 508, NULL, NULL, NULL, 1, 50, 15, 0, '2026-08-10 18:03:14', NULL, '2026-08-10 18:03:14'),
(508, 2, NULL, 'Тропа Земляного Гула', 'Из-под земли доносится едва слышный низкий гул, будто где-то глубоко внизу что-то ворочается.', NULL, NULL, NULL, 509, 507, NULL, NULL, 1, 50, 15, 0, '2026-08-10 18:03:09', NULL, '2026-08-10 18:03:09'),
(509, 2, NULL, 'Поляна Последнего Привала', 'Здесь ещё можно перевести дух — дальше тропа уходит в самую непроглядную часть чащи.', NULL, NULL, 510, NULL, 508, NULL, NULL, 1, 50, 15, 0, '2026-08-10 18:03:03', NULL, '2026-08-10 18:03:03'),
(510, 2, NULL, 'Край Непроглядной Чащи', 'Дальше деревья стоят так плотно, что тропа теряется в темноте — граница освоенного леса.', NULL, 509, NULL, NULL, NULL, NULL, NULL, 1, 50, 15, 0, NULL, NULL, '2026-08-10 18:01:22'),
