(898, 8, NULL, 'Тупик у Заваленного Хода', 'Дальнейший путь перегорожен обвалом земли и камней — придётся искать другую дорогу.', NULL, 897, NULL, NULL, NULL, NULL, NULL, 3, 70, 15, 0, '2026-08-11 10:16:30', NULL, '2026-08-11 10:16:30'),
(899, 8, NULL, 'Тоннель Царапин на Стенах', 'Глубокие борозды когтей исполосовали земляные стены на высоте волчьего роста.', NULL, 900, 891, NULL, NULL, NULL, NULL, 1, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(900, 8, NULL, 'Проход Пыльных Костей', 'Толстый слой земляной пыли покрывает старые кости, разбросанные вдоль всего прохода.', NULL, NULL, 899, NULL, 901, NULL, NULL, 1, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(901, 8, NULL, 'Тоннель Затхлого Воздуха', 'Воздух здесь неподвижен и затхл, будто эта часть кургана не знала притока свежего воздуха веками.', NULL, 902, NULL, 900, NULL, NULL, NULL, 2, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(902, 8, NULL, 'Развилка Ветхих Подпорок', 'Прогнившие деревянные подпорки едва держат свод — здесь стоит поторопиться.', NULL, 903, 901, NULL, NULL, NULL, NULL, 2, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(903, 8, NULL, 'Тоннель Могильного Праха', 'Тонкий серый прах покрывает пол ровным слоем, поднимаясь облачком при каждом шаге.', NULL, NULL, 902, 904, NULL, NULL, NULL, 2, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(904, 8, NULL, 'Тупик у Осиного Роя', 'Проход обрывается у крупного гнезда — гул растревоженных ос слышен ещё издалека.', NULL, NULL, NULL, NULL, 903, NULL, NULL, 3, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(905, 8, NULL, 'Перекрёсток Земляных Нор', 'Множество нор пронизывают стены этого перекрёстка — здесь явно обитает не одна тварь.', NULL, 906, 886, NULL, NULL, NULL, NULL, 1, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(906, 8, NULL, 'Тоннель Каплющей Сырости', 'Вода мерно каплет откуда-то сверху, оставляя на полу тёмные влажные пятна.', NULL, NULL, 905, NULL, 907, NULL, NULL, 1, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(907, 8, NULL, 'Проход Стёртых Рун', 'На стене едва различимы полустёртые резные символы — остатки древней защитной надписи.', NULL, NULL, NULL, 906, 908, NULL, NULL, 1, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(908, 8, NULL, 'Тоннель Костяной Крошки', 'Мелкая костяная крошка хрустит под ногами, будто здесь что-то долго перемалывало добычу.', NULL, 909, NULL, 907, 936, NULL, NULL, 1, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(909, 8, NULL, 'Проход Вздувшейся Земли', 'Пол здесь неровно вздулся буграми — под ним явно прорыты новые, ещё свежие ходы.', NULL, 910, 908, NULL, NULL, NULL, NULL, 1, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(910, 8, NULL, 'Тоннель Тяжёлого Молчания', 'Ни звука, ни шороха — тишина здесь давит сильнее, чем где-либо ещё в кургане.', NULL, 911, 909, NULL, NULL, NULL, NULL, 1, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(911, 8, NULL, 'Развилка Обугленных Подпорок', 'Деревянные подпорки здесь обуглены, хотя огня в этих ходах, казалось бы, взяться неоткуда.', NULL, NULL, 910, 912, 916, NULL, NULL, 1, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(912, 8, NULL, 'Тоннель Гнилых Досок', 'Остатки истлевших деревянных досок — обломки старого настила — устилают пол.', NULL, NULL, NULL, 913, 911, NULL, NULL, 1, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(913, 8, NULL, 'Проход Дрожащей Земли', 'Земля под ногами едва заметно вибрирует, будто где-то рядом движется что-то крупное.', NULL, NULL, 914, NULL, 912, NULL, NULL, 1, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(914, 8, NULL, 'Тоннель Слепых Нор', 'Множество тёмных нор уходят в стены — заглядывать в них лучше не стоит.', NULL, 913, NULL, 915, NULL, NULL, NULL, 1, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(915, 8, NULL, 'Тупик у Рухнувшей Балки', 'Массивная деревянная балка рухнула поперёк прохода, окончательно перекрыв путь.', NULL, NULL, NULL, NULL, 914, NULL, NULL, 3, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06');
INSERT INTO `locations` (`id`, `map_id`, `dungeon_id`, `name`, `description`, `image`, `north`, `south`, `east`, `west`, `up`, `down`, `count_monster`, `percent_respawn_monster`, `time_not_attack`, `is_locked`, `last_respawn_monster_at`, `created_at`, `updated_at`) VALUES
(916, 8, NULL, 'Проход Холодного Сквозняка', 'Ледяной сквозняк тянет из трещины в стене — источник его теряется где-то во тьме.', NULL, NULL, NULL, 911, 917, NULL, NULL, 1, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(917, 8, NULL, 'Тоннель Изрытых Стен', 'Земляные стены испещрены глубокими бороздами, оставленными когтями или клыками.', NULL, NULL, 918, 916, NULL, NULL, NULL, 1, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(918, 8, NULL, 'Проход Старой Кладки', 'Здесь ещё виден фрагмент древней каменной кладки — свидетельство того, что курган строили нарочно.', NULL, 917, NULL, NULL, 919, NULL, NULL, 1, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(919, 8, NULL, 'Тоннель Спутанных Корней', 'Толстые корни деревьев пробили свод и свисают вниз плотным переплетённым пологом.', NULL, NULL, NULL, 918, 920, NULL, NULL, 1, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(920, 8, NULL, 'Проход Сломанного Копья', 'Обломок ржавого копья торчит из земляной стены — след давнего, забытого сражения.', NULL, 921, NULL, 919, NULL, NULL, NULL, 2, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(921, 8, NULL, 'Тоннель Гулкого Дыхания', 'Из глубины хода доносится ровный, будто дышащий звук — источник его лучше не искать.', NULL, NULL, 920, NULL, 922, NULL, NULL, 2, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(922, 8, NULL, 'Проход Осыпавшейся Извёстки', 'Остатки извёстки осыпаются со стен при каждом шаге, обнажая голую утрамбованную землю.', NULL, NULL, NULL, 921, 923, NULL, NULL, 2, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(923, 8, NULL, 'Тупик у Заросшей Ниши', 'Небольшая погребальная ниша в стене заросла бледным мхом и паутиной — путь дальше обрывается.', NULL, NULL, NULL, 922, NULL, NULL, NULL, 3, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(924, 8, NULL, 'Тоннель Земляных Наростов', 'Странные бугристые наросты покрывают стены — то ли грибок, то ли гнёзда неведомых тварей.', NULL, NULL, 925, NULL, NULL, NULL, NULL, 3, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(925, 8, NULL, 'Проход Стёртых Ступеней', 'Едва заметные ступени, вырезанные прямо в земле, давно стёрлись от бесчисленных шагов.', NULL, 924, 926, NULL, NULL, NULL, NULL, 2, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(926, 8, NULL, 'Тоннель Могильной Сырости', 'Стены здесь всегда влажные на ощупь, сколько бы времени ни прошло с последнего дождя наверху.', NULL, 925, NULL, 927, NULL, NULL, NULL, 2, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(927, 8, NULL, 'Перекрёсток Костяных Обломков', 'Обломки крупных костей, расколотых явно не для еды, разбросаны по всему перекрёстку.', NULL, NULL, NULL, 928, 926, NULL, NULL, 2, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(928, 8, NULL, 'Проход Мерцающих Спор', 'В воздухе висят едва заметные светящиеся споры, оседая на коже холодной пылью.', NULL, NULL, 929, NULL, 927, NULL, NULL, 2, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(929, 8, NULL, 'Тоннель Глубоких Борозд', 'Глубокие параллельные борозды тянутся вдоль всего прохода — что-то тяжёлое волочилось здесь не раз.', NULL, 927, NULL, 930, NULL, NULL, NULL, 2, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(930, 8, NULL, 'Проход Забытого Оружия', 'Проржавевший клинок, наполовину вросший в земляную стену, — единственный след давнего гостя.', NULL, NULL, NULL, 931, 929, NULL, NULL, 1, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(931, 8, NULL, 'Тоннель Осиного Гула', 'Приглушённый гул слышен из-за стены — где-то рядом ещё одно гнездо, живое и потревоженное.', NULL, NULL, 932, NULL, 930, NULL, NULL, 1, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(932, 8, NULL, 'Проход Расколотого Черепа', 'Крупный, треснувший пополам череп неизвестного зверя лежит прямо посреди хода.', NULL, 931, NULL, 933, NULL, NULL, NULL, 1, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(933, 8, NULL, 'Тоннель Сплетённых Корней', 'Корни здесь переплелись так плотно, что образовали подобие грубой решётки поперёк прохода.', NULL, NULL, NULL, 934, 932, NULL, NULL, 1, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(934, 8, NULL, 'Развилка Древних Тайников', 'В стенах заметны небольшие ниши-тайники, давно пустые — их содержимое забрали ещё до вас.', NULL, NULL, 937, 935, 933, NULL, NULL, 1, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(935, 8, NULL, 'Тоннель Гнетущей Тишины', 'Тишина здесь особенно плотная, будто сам курган затаился в ожидании.', NULL, 936, NULL, NULL, 934, NULL, NULL, 1, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(936, 8, NULL, 'Проход Земляных Трещин', 'Сеть мелких трещин расходится по полу и стенам — курган будто медленно оседает сам в себя.', NULL, NULL, 935, 908, NULL, NULL, NULL, 1, 70, 15, 0, NULL, NULL, '2026-08-11 10:11:06'),
(937, 8, NULL, 'Тоннель Костяного Настила', 'Пол здесь неровно устлан старыми костями, вдавленными в утрамбованную землю.', NULL, 934, 938, NULL, NULL, NULL, NULL, 1, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(938, 8, NULL, 'Проход Влажного Мрака', 'Темнота тут особенно густая, а воздух пропитан сыростью настолько, что дышать тяжело.', NULL, 937, NULL, 939, NULL, NULL, NULL, 1, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(939, 8, NULL, 'Тоннель Изогнутых Опор', 'Деревянные опоры свода изогнуты под неестественным углом, будто их что-то годами теснило.', NULL, NULL, 940, NULL, 938, NULL, NULL, 1, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(940, 8, NULL, 'Проход Разодранной Ткани', 'Истлевшие обрывки савана свисают с торчащего из стены обломка кости.', NULL, 939, NULL, 941, NULL, NULL, NULL, 1, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(941, 8, NULL, 'Тоннель Первого Спуска', 'Отсюда виден слабый отблеск света со стороны входа — самая близкая к поверхности часть кургана.', NULL, NULL, NULL, 883, 940, NULL, NULL, 1, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(942, 8, NULL, 'Проход Земляных Ступеней', 'Грубо вырубленные в земле ступени ведут дальше, глубже под курган.', NULL, 883, 943, NULL, NULL, NULL, NULL, 1, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(943, 8, NULL, 'Тоннель Костяного Крошева', 'Мелкое костяное крошево толстым слоем устилает пол — здесь давно и часто кто-то охотится.', NULL, 942, NULL, 944, NULL, NULL, NULL, 1, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(944, 8, NULL, 'Проход Осклизлых Стен', 'Стены покрыты скользким налётом, отчего приходится идти особенно осторожно.', NULL, NULL, 945, NULL, 943, NULL, NULL, 1, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(945, 8, NULL, 'Тоннель Растревоженных Гнёзд', 'Тихий гул растревоженных ос доносится сразу из нескольких трещин в стенах.', NULL, 944, 946, NULL, NULL, NULL, NULL, 1, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(946, 8, NULL, 'Развилка Глубокого Кургана', 'Крупный перекрёсток ходов — отсюда курган расходится сразу в несколько направлений.', NULL, 945, NULL, 947, 961, NULL, NULL, 1, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(947, 8, NULL, 'Тоннель Земляных Червоточин', 'Стены изрыты вдоль и поперёк — здесь явно давно и активно роют.', NULL, NULL, NULL, 948, 946, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(948, 8, NULL, 'Проход Хрустящих Костей', 'Каждый шаг сопровождается хрустом мелких костей, скрытых под тонким слоем земли.', NULL, 952, 949, NULL, 947, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(949, 8, NULL, 'Тоннель Сгнившей Крепи', 'Деревянная крепь свода почти полностью сгнила, грозя обрушиться от любого резкого звука.', NULL, 948, NULL, 950, NULL, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(950, 8, NULL, 'Проход Бледного Свечения', 'Бледное свечение исходит от скоплений мха на потолке, освещая путь тусклым мертвенным светом.', NULL, NULL, NULL, 951, 949, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(951, 8, NULL, 'Тупик у Костяного Кургана', 'Груда костей, сваленных явно не случайно, преграждает дальнейший путь.', NULL, NULL, NULL, NULL, 950, NULL, NULL, 3, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(952, 8, NULL, 'Тоннель Глубоких Нор', 'Крупные норы уходят глубоко в стены — их обитатели явно крупнее обычных.', NULL, NULL, 948, 953, NULL, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(953, 8, NULL, 'Развилка Треснувшего Свода', 'Свод над этим перекрёстком испещрён трещинами, готовыми в любой момент осыпаться.', NULL, 954, NULL, 957, 952, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(954, 8, NULL, 'Тоннель Забытого Клинка', 'Сломанный клинок, вросший в земляной пол, — единственное напоминание о ком-то, кто прошёл здесь раньше.', NULL, 955, 953, NULL, NULL, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(955, 8, NULL, 'Проход Плотной Паутины', 'Паутина здесь настолько плотная, что напоминает ткань, натянутую от стены до стены.', NULL, NULL, 954, 956, NULL, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(956, 8, NULL, 'Тупик у Осиного Улья', 'Массивный осиный улей полностью перегораживает узкий проход — дальше не пройти, не потревожив его.', NULL, NULL, NULL, NULL, 955, NULL, NULL, 3, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(957, 8, NULL, 'Тоннель Каменных Обломков', 'Обломки старой каменной облицовки свода валяются вдоль всего прохода.', NULL, NULL, NULL, 958, 953, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(958, 8, NULL, 'Проход Могильной Пыли', 'Густая пыль поднимается в воздух при каждом шаге, оседая на губах горьким привкусом.', NULL, NULL, NULL, 959, 957, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(959, 8, NULL, 'Тоннель Волчьих Меток', 'Глубокие когтистые метки на стенах помечают территорию — здесь явно кто-то охраняет свои владения.', NULL, 960, NULL, NULL, 958, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(960, 8, NULL, 'Тупик у Обвалившегося Свода', 'Дальнейший путь полностью завален обрушившимся сводом — эта дорога окончена.', NULL, NULL, 959, NULL, NULL, NULL, NULL, 3, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(961, 8, NULL, 'Тоннель Земляного Гула', 'Низкий гул поднимается прямо из-под пола, будто где-то глубже что-то ворочается во сне.', NULL, NULL, NULL, 946, 962, NULL, NULL, 1, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(962, 8, NULL, 'Проход Разбитых Сосудов', 'Осколки погребальных сосудов хрустят под ногами при каждом шаге.', NULL, NULL, 963, 961, NULL, NULL, NULL, 1, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(963, 8, NULL, 'Тоннель Осевшей Земли', 'Пол здесь заметно осел, образовав неглубокую впадину посреди прохода.', NULL, 962, NULL, NULL, 964, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(964, 8, NULL, 'Проход Костяных Игл', 'Тонкие острые обломки костей торчат из стен, будто иглы гигантского зверя.', NULL, NULL, NULL, 963, 965, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(965, 8, NULL, 'Тоннель Глухого Треска', 'Откуда-то издалека доносится редкий глухой треск — будто трескается старое дерево или кость.', NULL, 966, NULL, 964, NULL, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(966, 8, NULL, 'Проход Слипшейся Паутины', 'Старая, слипшаяся от пыли паутина клочьями свисает с низкого свода.', NULL, 967, 965, NULL, NULL, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(967, 8, NULL, 'Тоннель Земляных Уступов', 'Пол неровными уступами спускается всё глубже под курган.', NULL, 969, 966, NULL, NULL, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(968, 8, NULL, 'Тупик у Костяного Алтаря', 'Грубо сложенный из костей алтарь стоит в конце прохода — назначение его лучше не выяснять.', NULL, NULL, NULL, NULL, 969, NULL, NULL, 3, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(969, 8, NULL, 'Развилка Осиных Троп', 'Множество узких лазов расходится отсюда — судя по гулу, это часть большого осиного гнезда.', NULL, NULL, 967, 968, 970, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(970, 8, NULL, 'Тоннель Мягкой Земли', 'Земля под ногами непривычно мягкая и рыхлая — этот ход прорыт совсем недавно.', NULL, NULL, NULL, 969, 971, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(971, 8, NULL, 'Проход Костяной Пыли', 'Тонкая костяная пыль оседает на всём вокруг, покрывая стены и пол ровным серым налётом.', NULL, NULL, NULL, 970, 972, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(972, 8, NULL, 'Развилка Древних Ниш', 'Ряд полуразрушенных погребальных ниш тянется вдоль стен этого перекрёстка.', NULL, 973, 977, 971, NULL, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(973, 8, NULL, 'Тоннель Глубокой Сырости', 'Влага здесь сочится прямо из земляных стен, собираясь в мелкие лужицы на полу.', NULL, 974, 972, NULL, NULL, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(974, 8, NULL, 'Проход Стёртых Знаков', 'На потрескавшейся стене едва различимы остатки древних предостерегающих знаков.', NULL, NULL, 973, 975, NULL, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(975, 8, NULL, 'Тоннель Костяного Крошева', 'Мелкие обломки костей хрустят под ногами на протяжении всего прохода.', NULL, 976, NULL, NULL, 974, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(976, 8, NULL, 'Тупик у Червоточного Гнезда', 'Проход обрывается у крупного скопления нор — оттуда доносится влажный, тяжёлый шорох.', NULL, NULL, 975, NULL, NULL, NULL, NULL, 3, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(977, 8, NULL, 'Проход Осевших Опор', 'Деревянные опоры свода просели под тяжестью земли, накренившись под опасным углом.', NULL, 972, 978, NULL, NULL, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(978, 8, NULL, 'Тоннель Гулкой Пустоты', 'Звук шагов отдаётся здесь странным гулким эхом, будто рядом скрыта большая пустая полость.', NULL, 977, NULL, NULL, 979, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(979, 8, NULL, 'Проход Могильных Реликвий', 'Осколки старых украшений и утвари виднеются среди земли — то, что не успели забрать мародёры.', NULL, NULL, NULL, 978, 980, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(980, 8, NULL, 'Тоннель Мерцающих Спор', 'Едва заметные светящиеся споры кружат в воздухе, оседая на коже холодной пылью.', NULL, 981, NULL, 979, NULL, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(981, 8, NULL, 'Проход Волчьего Логова', 'Крупная утоптанная площадка и обглоданные кости выдают чьё-то постоянное логово неподалёку.', NULL, NULL, 980, NULL, 982, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(982, 8, NULL, 'Тоннель Земляных Складок', 'Стены здесь собраны неровными складками, будто земля когда-то текла, а потом застыла.', NULL, 983, NULL, 981, NULL, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(983, 8, NULL, 'Проход Тихого Шелеста', 'Едва слышный шелест доносится из темноты впереди — источник его разглядеть не удаётся.', NULL, 984, 982, NULL, NULL, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(984, 8, NULL, 'Тоннель Костяной Стены', 'Вдоль одной из стен аккуратно, будто нарочно, уложены человеческие и звериные кости.', NULL, 985, 983, NULL, NULL, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(985, 8, NULL, 'Проход Глубокой Тьмы', 'Тьма здесь настолько плотная, что кажется почти осязаемой.', NULL, NULL, 984, 986, NULL, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(986, 8, NULL, 'Тоннель Осыпающихся Сводов', 'Земля с потолка сыпется тонкой струйкой практически без остановки.', NULL, 987, NULL, NULL, 985, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(987, 8, NULL, 'Проход Забытых Шагов', 'Едва заметные следы — человеческие и звериные вперемешку — ведут дальше во тьму.', NULL, 988, 986, NULL, NULL, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(988, 8, NULL, 'Развилка Последних Троп', 'Крупный перекрёсток — судя по всему, один из последних перед самым сердцем кургана.', NULL, NULL, 987, 989, 990, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(989, 8, NULL, 'Тупик у Древнего Идола', 'Грубо вытесанная из камня фигура, полустёртая временем, стоит в конце прохода.', NULL, NULL, NULL, NULL, 988, NULL, NULL, 3, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(990, 8, NULL, 'Тоннель Тяжёлого Духа', 'Воздух здесь густой и тяжёлый, будто пропитан чем-то древним и голодным.', NULL, 991, NULL, 988, NULL, NULL, NULL, 2, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06'),
(991, 8, NULL, 'Порог Чрева Кургана', 'Тоннель здесь расширяется, а земля под ногами странно тёплая — где-то совсем рядом бьётся сердце кургана.', NULL, NULL, 990, NULL, NULL, NULL, NULL, 3, 70, 15, 0, NULL, '2026-08-02 21:11:19', '2026-08-11 10:11:06');
