INSERT INTO `npcs` (`id`, `location_id`, `name`, `description`, `image`, `created_at`, `updated_at`) VALUES
(1, 6, 'Эйдран', 'Эйдран — глава города и хранитель порядка на главной площади. В прошлом он вел городскую дружину в походах, а теперь принимает путников у целительного фонтана, следит за безопасностью улиц и направляет молодых воинов туда, где их сила нужнее всего.', '/img/npc/stareyshina.jpg', '2026-06-16 19:36:02', '2026-07-19 13:08:18'),
(2, 4, 'Мудрый Финко', 'Мудрец и хранитель знаний. Говорят, он помнит историю долины лучше любых летописей.', '/img/npc/arhivarius.jpg', '2026-06-16 19:36:02', '2026-07-16 12:47:21'),
(3, 4, 'Воевода Гидвер', 'Дока военного искусства, тактик и стратег, он посвятил свою жизнь развитию военного дела и обучению молодых солдат его премудростям.', '/img/npc/voevoda.jpg', '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(4, 305, 'Егерь Вульфгар', 'Старый егерь Ордена Охотников. Ведёт учёт контрактов на чудовищ долины и выдаёт задания тем, кто сумел добраться так далеко.', '/storage/npc/vdbvNcytkQ7jNrm6leu3JFeCTxrdm9HREyNSW3xn.png', '2026-07-16 12:47:20', '2026-08-11 15:13:51'),
(6, 29, 'Архивариус Вудугри', 'Архивариус Вудугри — архивариус Регистрационной палаты, лицо, уполномоченное регистрировать кланы расы древних и хранить их архивы.', '/img/npc/arhivarius.jpg', '2026-07-17 11:31:30', '2026-07-17 11:31:30'),
(7, 27, 'Кузнец Тородин', 'Кузнец Тородин — коренастый мастер с обожжёнными руками и зорким глазом. Говорят, нет такого клинка, что он не смог бы наточить, и такой брони, что не сумел бы закалить.', '/img/npc/kuznec.jpg', '2026-07-17 12:51:42', '2026-07-17 12:53:20'),
(8, 39, 'Гринт Медяш', 'Гринт Медяш — гном-брокер Площади торгов, который знает цену каждой вещи еще до того, как владелец успеет назвать сумму. Он следит за комиссионными сделками, присматривает за заявками на бирже и с хриплой усмешкой подсказывает путникам, где выгоднее продать трофей или найти редкую покупку.', '/img/npc/npc_gnom.jpg', '2026-07-17 14:39:48', '2026-07-17 14:39:48'),
(9, 46, 'Борин Златоключ', 'Борин Златоключ — строгий хранитель городского банка и клановой казны. Он привык считать не слова, а монеты, ведет книги вкладов без единой помарки и знает, кому доверены личные сундуки, а кому — богатства целого клана. У его стойки можно сохранить ценности, проверить запасы и передать имущество туда, где оно будет надежнее, чем в дорожной сумке.', '/img/npc/bank.jpg', '2026-07-17 14:52:50', '2026-07-17 14:52:50'),
(10, 16, 'Бранн Сталерук', 'Бранн Сталерук — хозяин лавок Оружейного ряда и опытный мастер, который с первого взгляда отличает боевой клинок от красивой безделушки. Его руки покрыты следами старых ожогов и зазубрин, а голос привык перекрывать звон молотов. Бранн помогает путникам подобрать оружие, примерить броню и понять, какое снаряжение выдержит настоящую схватку.', '/img/npc/kristal_shahterwarr.jpg', '2026-07-19 11:32:02', '2026-07-19 12:23:37'),
(11, 18, 'Тарвин', 'Тарвин — расторопный хозяин Торговой лавки, который держит под рукой все, что нужно путнику перед дорогой: простую еду, полезные припасы и эликсиры на случай тяжелой схватки. Он редко повышает голос, но всегда помнит, кому что продал и кто вернулся за добавкой после удачной охоты.', '/img/npc/flaviy.jpg', '2026-07-19 12:16:16', '2026-07-19 12:21:44');
INSERT INTO `npc_dialogue_nodes` (`id`, `npc_id`, `title`, `description`, `is_start`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 4, 'Егерь Вульфгар', 'Стой, путник. Немногие доходят до этого тракта своими ногами — чаще их приносят. Я — Вульфгар, егерь Ордена Охотников. Сорок лет я читаю следы этой долины, и поверь: каждый след здесь ведёт либо к добыче, либо к смерти.', 1, 1, 0, '2026-07-16 12:55:57', '2026-07-16 12:55:57'),
(2, 4, 'История Ордена', 'Когда-то за этим перевалом стояла застава Серых Клинков. Гарнизон пал за одну ночь: с гор спустились ледяные великаны, а из пепелища поднялась нежить. Уцелели лишь охотники — те, кто умел выследить зверя раньше, чем зверь выследит их. Так родился Орден: не армия и не гильдия, а братство тех, кто берёт контракты на чудовищ и доводит их до конца. Наш девиз прост: «След не лжёт».', 0, 1, 1, '2026-07-16 12:55:57', '2026-07-16 12:55:57'),
(3, 4, 'Контракты Ордена', 'Всё просто, как хороший капкан. Я выдаю контракты — на мантикор, виверн, великанов, а для бывалых — на драконов и владык нежити. Исполнил — и Орден узнаёт твоё имя чуть лучше. Чем выше твоя слава, тем опаснее контракты и щедрее награды. Но запомни: один контракт за раз, и после сдачи — два дня тишины. Хороший охотник не гонится за всей дичью разом.', 0, 1, 2, '2026-07-16 12:55:57', '2026-07-16 12:55:57'),
(4, 4, 'Медали и подвиги', 'Хе… Медали Ордена не покупают очками славы. Каждая выкована из клыка первой добычи наших основателей, и каждая вручается только за подвиг. Наберёшь славу — приходи, и я назову твоё испытание: упокоить лича, вырвать сердце ледяного великана… А высшая награда, «Легенда», потребует трёх подвигов кряду. Таких охотников за мою жизнь было двое. Может, станешь третьим.', 0, 1, 3, '2026-07-16 12:55:57', '2026-07-16 12:55:57'),
(5, 7, 'Кузнец Тородин', 'Здорово, странник! Слышишь этот звон? Это моя работа. Я — мастер-кузнец Тородин, и в моём ряду любое железо обретает вторую жизнь. С чем пожаловал?', 1, 1, 0, '2026-07-17 12:51:42', '2026-07-17 12:52:37'),
(6, 7, 'Услуги кузни', 'В моей кузне для тебя найдётся дело:\n— Заточка — поднимаю мощь оружия и брони;\n— Камни — вставляю самоцветы в сокеты предмета;\n— Руны — вплавляю руны, дарующие особые свойства;\n— Крафт — кую новое снаряжение из материалов;\n— Разбор — разбиваю ненужную вещь обратно на материалы.\nВыбирай вкладку сверху — и приступим.', 0, 1, 1, '2026-07-17 12:51:42', '2026-07-17 12:51:42'),
(7, 7, 'Про заточку', 'Заточка — первое дело для любого воина. Неси оружие или броню, материалы для заточки — и я подниму их характеристики. Чем выше уровень заточки, тем крепче клинок и надёжнее доспех. Но помни: чем выше ступень, тем дороже и рискованнее работа.', 0, 1, 2, '2026-07-17 12:51:42', '2026-07-17 12:51:42'),
(8, 7, 'Про камни и руны', 'Сокеты сами по себе не появляются — сперва нужна оправа. Оправы бывают четырёх редкостей: обычная, необычная, редкая и эпическая — чем реже оправа, тем больше сокетов она способна открыть, но и плата за работу выше. Оправу ставят один раз, а если позже принесёшь оправу получше — рискну переставить, но если число сокетов не увеличится, оправа и золото уйдут впустую.\n\nКогда сокеты открыты — неси самоцветы, я вставлю их в гнёзда. Самоцветы бывают пяти видов — силы, мудрости, ловкости, интуиции и интеллекта — каждый поднимает свою характеристику. И у каждого вида пять ступеней: малый даёт +1, обычный самоцвет — +2, великий — +3, большой — +4, а абсолютный — целых +5 к характеристике. Выбирай под свою сборку.\n\nРуны — статья особая: их вплавляют в рунные слоты, и они дают предмету редкие свойства и пассивные умения. Захочешь — перекую руну заново, если её сила тебя не устроит.', 0, 1, 3, '2026-07-17 12:51:42', '2026-07-18 11:03:24'),
(9, 7, 'Про крафт и разбор', 'Есть у тебя чертёж и материалы — выкую новое снаряжение с нуля. А если вещь отслужила своё — не выбрасывай: разберу её на кузне и верну часть материалов, что пойдут на новые изделия.', 0, 1, 4, '2026-07-17 12:51:42', '2026-07-17 12:51:42'),
(10, 8, 'Гринт Медяш', 'Хо-хо, свежий взгляд на старые прилавки! Я Гринт Медяш, смотритель сделок на Площади торгов. Здесь два дома рядом: комиссионный магазин для готовых лотов и биржа для заявок. Хочешь понять, куда идти с добычей?', 1, 1, 0, '2026-07-17 14:46:22', '2026-07-17 14:46:22'),
(11, 8, 'Комиссионный магазин', 'В комиссионном магазине игроки выставляют свои вещи на продажу. Видишь подходящий лот — покупаешь сразу по назначенной цене. Хочешь продать свое — выставляешь предмет, указываешь цену и ждешь покупателя. Это место для тех, кто уже знает, за сколько готов расстаться с вещью.', 0, 1, 1, '2026-07-17 14:46:22', '2026-07-17 14:46:22'),
(12, 8, 'Продажа и покупка лотов', 'Для покупки смотри список лотов, сравнивай цену и свойства предмета. Для продажи выбирай вещь из рюкзака, ставь количество и цену. Не жадничай: слишком дорогой лот будет пылиться, слишком дешевый купят раньше, чем ты успеешь передумать. Следи за редкостью, уровнем предмета и спросом на экипировку.', 0, 1, 2, '2026-07-17 14:46:22', '2026-07-17 14:46:22'),
(13, 8, 'Биржа заявок', 'Биржа работает иначе. Там игроки создают заявки на покупку: какой предмет нужен, сколько штук и по какой цене. Если у тебя есть такой товар, ты можешь закрыть заявку и сразу получить оплату. Это удобно, когда покупатель ищет конкретный ресурс или вещь, а продавец не хочет ждать, пока кто-то заметит его лот.', 0, 1, 3, '2026-07-17 14:46:22', '2026-07-17 14:46:22'),
(14, 8, 'Советы торговца', 'Комиссионный магазин хорош для редких вещей и экипировки с понятной ценой. Биржа хороша для ходовых ресурсов и предметов, которые часто скупают пачками. Перед сделкой смотри не только цену, но и количество, свойства предмета и то, как быстро тебе нужны монеты. Терпеливый торговец богатеет чаще вспыльчивого.', 0, 1, 4, '2026-07-17 14:46:22', '2026-07-17 14:46:22'),
(15, 9, 'Борин Златоключ', 'Добро пожаловать в Банковский двор. Здесь не машут мечами и не торгуются на крике — здесь считают, хранят и отвечают за каждую монету. Я Борин Златоключ. Запомни главное: и городской банк, и клановая казна работают только с деньгами. Вещи, ресурсы и снаряжение сюда не принимаются.', 1, 1, 0, '2026-07-17 14:57:22', '2026-07-17 15:00:09'),
(16, 9, 'Городской банк', 'Городской банк хранит твои личные деньги. Можно положить монеты на счет, забрать их обратно, проверить баланс и держать запас отдельно от того, что носишь с собой. Это не склад и не хранилище предметов: броню, оружие, ресурсы и прочие вещи банк не принимает.', 0, 1, 1, '2026-07-17 14:57:22', '2026-07-17 15:00:09'),
(17, 9, 'Клановая казна', 'Клановая казна хранит общие деньги братства. Сюда участники могут вносить монеты для нужд клана, а доступ к снятию зависит от прав, выданных руководством. Казна не принимает предметы и ресурсы — только деньги, чтобы казначеи ясно видели, сколько средств у клана на общие цели.', 0, 1, 2, '2026-07-17 14:57:22', '2026-07-17 15:00:09'),
(18, 9, 'Советы хранителя', 'Не путай назначение мест хранения. Личные монеты держи в городском банке, чтобы не таскать весь запас с собой. Деньги клана вноси в клановую казну, если они нужны для общих расходов. А предметы, ресурсы и снаряжение ищи где хранить в других местах — банковские книги считают только монеты.', 0, 1, 3, '2026-07-17 14:57:22', '2026-07-17 15:00:09'),
(19, 10, 'Бранн Сталерук', 'Добро пожаловать в Магазин снаряжения. Здесь покупают то, что держит в живых за городскими воротами: оружие, щиты, броню и прочую экипировку. Я Бранн Сталерук, слежу, чтобы на полках лежало не украшение для стены, а вещи для настоящего боя.', 1, 1, 0, '2026-07-19 12:02:31', '2026-07-19 12:02:31'),
(20, 10, 'Покупка снаряжения', 'В разделе покупки можно выбрать оружие, щиты и броню для своего уровня. Смотри не только на цену, но и на требования предмета: уровень, характеристики и назначение. Хороший клинок бесполезен, если ты не можешь его удержать, а тяжелая броня не спасет того, кто не готов к ее весу.', 0, 1, 1, '2026-07-19 12:02:31', '2026-07-19 12:02:31'),
(21, 10, 'Продажа вещей', 'В разделе продажи можно сдать лишние предметы из рюкзака и получить монеты. Магазин выкупает вещи дешевле их полной цены, зато сделка проходит сразу. Перед продажей проверь, не пригодится ли предмет для другого комплекта, квеста, обмена или будущего уровня.', 0, 1, 2, '2026-07-19 12:02:31', '2026-07-19 12:02:31'),
(22, 10, 'Советы оружейника', 'Обновляй снаряжение не по одной цифре урона. Для охоты важна связка: оружие задает темп боя, щит и броня держат удар, а требования предметов должны совпадать с твоей прокачкой. Если собираешься играть танком, критовиком или уворотом, подбирай вещи под этот путь заранее.', 0, 1, 3, '2026-07-19 12:02:31', '2026-07-19 12:02:31'),
(23, 11, 'Тарвин', 'Добро пожаловать в Торговую лавку. Здесь ты найдешь простую еду для быстрого перекуса и эликсиры на случай тяжелой схватки — все, что нужно путнику перед дорогой. Я Тарвин, слежу, чтобы полки не пустовали, а цены оставались честными.', 1, 1, 0, '2026-07-19 15:41:41', '2026-07-19 15:41:41'),
(24, 11, 'Раздел «Еда»', 'В разделе еды продаются груши, виноград, сдобные булочки, хлеб, мясные пироги и окорока — все это восстанавливает часть здоровья при использовании. Есть еда и посытнее: сыр, шашлык из мяса кодрагов, индюшачья нога, а для тех, кто не жалеет монет — заморские фрукты, запеченная рыба и черника. Чем реже продукт, тем больше здоровья он возвращает.', 0, 1, 1, '2026-07-19 15:41:41', '2026-07-19 15:41:41'),
(25, 11, 'Раздел «Эликсиры»', 'Эликсиры действуют сильнее обычной еды и разом восстанавливают заметную долю здоровья или маны. Держи один-два про запас перед вылазкой в опасные земли — в бою заменить их будет уже некогда.', 0, 1, 2, '2026-07-19 15:41:41', '2026-07-19 15:41:41'),
(26, 11, 'Советы торговца', 'Не трать все монеты на дорогие эликсиры, если рядом есть простая еда — она дешевле и почти всегда выручает в спокойной охоте. А вот перед боссом или дальней вылазкой лучше взять что-то посерьезнее из редких припасов.', 0, 1, 3, '2026-07-19 15:41:41', '2026-07-19 15:41:41');
INSERT INTO `npc_dialogue_options` (`id`, `npc_dialogue_node_id`, `to_node_id`, `button_text`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 1, 2, 'Что за Орден Охотников?', 1, 0, '2026-07-16 12:55:57', '2026-07-16 12:55:57'),
(2, 1, 3, 'Какая работа найдётся для меня?', 1, 1, '2026-07-16 12:55:57', '2026-07-16 12:55:57'),
(3, 2, 3, 'Как мне заслужить доверие Ордена?', 1, 0, '2026-07-16 12:55:57', '2026-07-16 12:55:57'),
(4, 3, 4, 'А медали? Я слышал о них.', 1, 0, '2026-07-16 12:55:57', '2026-07-16 12:55:57'),
(5, 5, 6, 'Какие услуги ты предлагаешь?', 1, 0, '2026-07-17 12:51:42', '2026-07-17 12:51:42'),
(6, 6, 7, 'Расскажи про заточку.', 1, 0, '2026-07-17 12:51:42', '2026-07-17 12:51:42'),
(7, 6, 8, 'А камни и руны?', 1, 1, '2026-07-17 12:51:42', '2026-07-17 12:51:42'),
(8, 6, 9, 'Крафт и разбор?', 1, 2, '2026-07-17 12:51:42', '2026-07-17 12:51:42'),
(9, 10, 11, 'Что можно делать в комиссионном магазине?', 1, 0, '2026-07-17 14:46:22', '2026-07-17 14:46:22'),
(10, 10, 13, 'Чем биржа отличается от аукциона?', 1, 1, '2026-07-17 14:46:22', '2026-07-17 14:46:22'),
(11, 10, 14, 'Дай совет по торговле.', 1, 2, '2026-07-17 14:46:22', '2026-07-17 14:46:22'),
(12, 11, 12, 'Как правильно покупать и продавать лоты?', 1, 0, '2026-07-17 14:46:22', '2026-07-17 14:46:22'),
(13, 12, 13, 'А если я хочу продать по заявке?', 1, 0, '2026-07-17 14:46:22', '2026-07-17 14:46:22'),
(14, 13, 14, 'Когда лучше пользоваться биржей?', 1, 0, '2026-07-17 14:46:22', '2026-07-17 14:46:22'),
(15, 15, 16, 'Что можно делать в банке?', 1, 0, '2026-07-17 14:57:22', '2026-07-17 14:57:22'),
(16, 15, 17, 'Что такое клановая казна?', 1, 1, '2026-07-17 14:57:22', '2026-07-17 14:57:22'),
(17, 15, 18, 'Как лучше хранить деньги?', 1, 2, '2026-07-17 14:57:22', '2026-07-17 15:00:09'),
(18, 16, 18, 'Что стоит держать в банке?', 1, 0, '2026-07-17 14:57:22', '2026-07-17 14:57:22'),
(19, 17, 18, 'Как не смешивать личные и клановые деньги?', 1, 0, '2026-07-17 14:57:22', '2026-07-17 15:00:09'),
(20, 19, 20, 'Что здесь можно купить?', 1, 0, '2026-07-19 12:02:31', '2026-07-19 12:02:31'),
(21, 19, 21, 'Как продать лишние вещи?', 1, 1, '2026-07-19 12:02:31', '2026-07-19 12:02:31'),
(22, 19, 22, 'Как выбирать снаряжение?', 1, 2, '2026-07-19 12:02:31', '2026-07-19 12:02:31'),
(23, 20, 22, 'На что смотреть при покупке?', 1, 0, '2026-07-19 12:02:31', '2026-07-19 12:02:31'),
(24, 21, 22, 'Что лучше не продавать сразу?', 1, 0, '2026-07-19 12:02:31', '2026-07-19 12:02:31'),
(25, 23, 24, 'Что у вас есть из еды?', 1, 0, '2026-07-19 15:41:41', '2026-07-19 15:41:41'),
(26, 23, 25, 'А что с эликсирами?', 1, 1, '2026-07-19 15:41:41', '2026-07-19 15:41:41'),
(27, 23, 26, 'Есть советы перед покупкой?', 1, 2, '2026-07-19 15:41:41', '2026-07-19 15:41:41'),
(28, 24, 26, 'Что лучше взять с собой?', 1, 0, '2026-07-19 15:41:41', '2026-07-19 15:41:41'),
(29, 25, 26, 'Когда их лучше применять?', 1, 0, '2026-07-19 15:41:41', '2026-07-19 15:41:41');
