INSERT INTO `quests` (`id`, `title`, `description`, `type`, `start_npc_id`, `complete_npc_id`, `parent_quest_id`, `after_quest_id`, `reset_period`, `is_active`, `is_finish`, `created_at`, `updated_at`) VALUES
(1, 'Познание мира', 'Уфф... Давненько до такого не доходило! Но вы, воин, вовремя подоспели и\n                                                задали им! Простите, что втянул вас в этот бой. Многие воины погибли от\n                                                их зубов, а чудища всё прибывают… Страшусь даже подумать, что будет\n                                                дальше. <br> Постойте, я не помню вас среди жителей города, воин. Вы\n                                                здесь недавно? <br> В таком случае раскрываю свои объятия и говорю:\n                                                добро пожаловать, друг! Я здешний наставник, управляю этим местом. <br>\n                                                Если хочешь внести свою лепту в общее дело, покажи свою силу в битве с\n                                                ужасными <span><b class=\"blue\">Неферто</b> </span>, добыв\n                                                при этом – их Соцветие!\n                                                А теперь ступай и постарайтесь не обмануть мои ожидания!', 'main', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(2, 'Первая вылазка', 'Ты показал себя неплохим бойцом. Теперь иди в Шепчущий лес и разберись с летучими мышами.', 'one_time', 1, 1, NULL, 1, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(3, 'Испытание воли', 'Настоящий воин сражается на нескольких фронтах одновременно. Уничтожь мышей и летучих мышей.', 'one_time', 1, 1, NULL, 2, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(4, 'Путь к катакомбам', 'Мне нужно, чтобы ты передал Кристалл моему посланнику Вестнику у восточных ворот. Он откроет тебе путь к Тропе Заблудших.', 'one_time', 1, 3, NULL, 3, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(5, 'Дозор у ворот', 'Мышиные стаи снова атакуют ворота! Убей 20 мышей. Это задание можно выполнять каждый день.', 'repeatable', 1, 1, NULL, 1, 86400, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(6, 'Три испытания', 'Докажи свою доблесть, пройдя три испытания. Тебе предстоит сражаться, охотиться и выполнить особое поручение.', 'one_time', 1, 1, NULL, 3, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(7, 'Охота на грызунов', 'Мышиные стаи угрожают нашим амбарам. Кlan должен разобраться с этой угрозой — уничтожьте 30 мышей.', 'clan', 1, 1, NULL, NULL, 86400, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(8, 'Налёт летучих мышей', 'Стаи летучих мышей атакуют ночные дозоры. Клан должен уничтожить 50 летучих мышей и восстановить порядок.', 'clan', 1, 1, NULL, NULL, 172800, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(9, 'Угроза драконов', 'Древние драконы вырвались из подземелий и сеют хаос. Клану поручено уничтожить 20 Древних драконов.', 'clan', 1, 1, NULL, NULL, 604800, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(10, 'Противостояние нежити', 'Лич Некромант поднимает легионы нежити. Клан обязан уничтожить 15 Личей Некромантов и 10 Властелинов Нежити.', 'clan', 1, 1, NULL, NULL, 604800, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(11, 'Чёрная угроза', 'Демоны и вампиры вышли из тёмных глубин. Клану предстоит уничтожить 10 Демонов Регенерации и 10 Древних вампиров.', 'clan', 1, 1, NULL, NULL, 259200, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(12, '[Стража] Мыши в амбарах', 'Мыши атакуют городские амбары. Уничтожьте 10 мышей.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(13, '[Стража] Грызуны у стен', 'Отряды мышей снуют у городских стен. Убейте 15 мышей.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(14, '[Стража] Летучие разведчики', 'Летучие мыши кружат над стражей, мешая дозорам. Уничтожьте 8.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(15, '[Стража] Ночной дозор', 'Очистите ночные кварталы от мышей и летучих мышей.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(16, '[Стража] Ночные гости', 'Стаи летучих мышей нарушают ночной покой города. Убейте 12.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(17, '[Стража] Вылазка нежити', 'Летучие мыши и Древние драконы угрожают окрестностям. Уничтожьте обоих.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(18, '[Стража] Дракон у ворот', 'Древние драконы появились у ворот города. Уничтожьте 15.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(19, '[Стража] Зачистка предместий', 'Предместья кишат летучими мышами. Зачистите — убейте 20.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(20, '[Стража] Двойной удар', 'Атака с неба — драконы и летучие мыши действуют сообща.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(21, '[Стража] Ночная вахта', 'Долгая ночная вахта — уничтожьте 25 мышей и 5 драконов.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(22, '[Стража] Некроманты наступают', 'Армия личей надвигается на город. Остановите её — уничтожьте 10 Личей Некромантов.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(23, '[Стража] Вампирский ковен', 'Ковен вампиров обосновался в предместьях. Уничтожьте 15 Древних вампиров.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(24, '[Стража] Двойная угроза', 'Личи и вампиры действуют сообща. Уничтожьте и тех, и других.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(25, '[Стража] Страж некрополя', 'Некрополь поднимает всё больше личей. Уничтожьте 20.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(26, '[Стража] Осада мертвецов', 'Мертвецы осаждают городские стены. Проредите их ряды.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(27, '[Стража] Демоническое вторжение', 'Демоны Регенерации ломятся в городские ворота. Остановите 10.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(28, '[Стража] Властелины тьмы', 'Властелины Нежити командуют ордами. Уничтожьте 8 лидеров.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(29, '[Стража] Элитный карательный отряд', 'Элитные демоны и властелины угрожают городу. Уничтожьте обоих.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(30, '[Стража] Волна тьмы', 'Тёмная волна демонов захлёстывает окрестности. Уничтожьте 15.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(31, '[Стража] Армия нежити', 'Армия Властелинов Нежити надвигается. Уничтожьте 12.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(32, '[Стража] Последний рубеж', 'Оборонительный рубеж города. Уничтожьте демонов и властелинов.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(33, '[Стража] Бесконечная тьма', 'Тьма не отступает. Уничтожьте 20 Демонов Регенерации.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(34, '[Стража] Хаос нежити', 'Хаос нежити охватил регион. Уничтожьте 18 Властелинов.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(35, '[Стража] Финальный бой', 'Финальное сражение за судьбу города. Уничтожьте всех.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(36, '[Стража] Вечный страж', 'Задание для истинных защитников города. Уничтожьте 25 Демонов.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(37, '[Стража] Повелитель тьмы', 'Только командир стражи способен справиться. Уничтожьте 25 Властелинов.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(38, '[Стража] Чистильщик мрака', 'Окончательно очистите мир от тёмных сил.', 'reputation', 1, 1, NULL, NULL, NULL, 1, 0, '2026-06-16 19:36:02', '2026-06-16 19:36:02'),
(95, '[Орден] Хвост скорпиона, морда льва', 'Мантикоры расплодились у дороги в поселение. Убейте 8.', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:20', '2026-07-17 05:59:41'),
(96, '[Орден] Шипы для алхимика', 'Алхимикам Ордена нужны шипы мантикор. Добудьте 5 штук.', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:20', '2026-07-17 05:59:41'),
(97, '[Орден] Небесные хищницы', 'Виверны охотятся на путников. Собейте 6.', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:20', '2026-07-17 05:59:41'),
(98, '[Орден] Двойная вылазка', 'Проредите и мантикор, и виверн разом.', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:20', '2026-07-17 05:59:41'),
(99, '[Орден] Крылья на стену', 'Охотничий зал Ордена украшают крылья виверн. Принесите 4.', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:20', '2026-07-17 05:59:41'),
(100, '[Орден] Холод с гор', 'Ледяные великаны спустились с гор. Убейте 6.', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:20', '2026-07-17 05:59:41'),
(101, '[Орден] Большая охота', 'Виверны и великаны — добыча для опытного охотника.', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:20', '2026-07-17 05:59:41'),
(102, '[Орден] Сердце стужи', 'Добудьте 3 ледяных сердца — они не тают даже летом.', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:20', '2026-07-17 05:59:41'),
(103, '[Орден] Первый дракон', 'Молодые драконы — серьёзная добыча. Убейте 5.', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:20', '2026-07-17 05:59:41'),
(104, '[Орден] Лёд и пламя', 'Великаны и драконы не поделили угодья. Помогите — уничтожьте обоих.', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:20', '2026-07-17 05:59:41'),
(105, '[Орден] Чешуйчатый доспех', 'Кузнецам Ордена нужна драконья чешуя. Добудьте 4.', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:20', '2026-07-17 05:59:41'),
(106, '[Орден] Древний ужас', 'Древний дракон снова поднялся. Одолейте его дважды.', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:20', '2026-07-17 05:59:41'),
(107, '[Орден] Охота на некроманта', 'Лич Некромант поднимает мёртвых охотников. Упокойте его.', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:20', '2026-07-17 05:59:41'),
(108, '[Орден] Кровь за кровь', 'Древние вампиры пьют кровь путников. Уничтожьте 3.', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:20', '2026-07-17 05:59:41'),
(109, '[Орден] Неубиваемый', 'Демон Регенерации восстаёт вновь и вновь. Убейте 3 — окончательно.', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:20', '2026-07-17 05:59:41'),
(110, '[Орден] Ночь мастера охоты', 'Вампиры и драконы за одну ночь. Справитесь?', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:20', '2026-07-17 05:59:41'),
(111, '[Орден] Повелитель мёртвых', 'Властелин Нежити — вершина охоты. Убейте 2.', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:20', '2026-07-17 05:59:41'),
(112, '[Орден] Элитный контракт', 'Контракт на демонов и властелинов. Только для элиты Ордена.', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:20', '2026-07-17 05:59:41'),
(113, '[Орден] Легендарная охота', 'Задание, о котором слагают песни. Убейте 4 Властелинов Нежити.', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:20', '2026-07-17 05:59:41'),
(114, '[Орден] Эссенция тьмы', 'Добудьте тёмную эссенцию из самого сердца нежити.', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:20', '2026-07-17 05:59:41'),
(115, '[Орден] Великое истребление', 'Очистите долину от сильнейших тварей.', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:20', '2026-07-17 05:59:41'),
(116, '[Орден] Подвиг: Первое упокоение', 'Медаль «Охотник» получает лишь тот, кто в одиночку упокоил Лича Некроманта.', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:20', '2026-07-17 05:59:41'),
(117, '[Орден] Подвиг: Крылатый след', 'Следопыт читает небо как книгу. Добудьте 5 крыльев виверны.', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:20', '2026-07-17 05:59:41'),
(118, '[Орден] Подвиг: Ночной ловчий', 'Вампиры веками ускользали от Ордена. Убейте 3 Древних вампиров.', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:21', '2026-07-17 05:59:41'),
(119, '[Орден] Подвиг: Сердце зимы', 'Ледяное сердце не должно растаять в пути. Принесите 3.', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:21', '2026-07-17 05:59:41'),
(120, '[Орден] Подвиг: Окончательная смерть', 'Демоны Регенерации не умирают… обычно. Убейте 5 — навсегда.', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:21', '2026-07-17 05:59:41'),
(121, '[Орден] Подвиг: Испытание чешуёй', 'Первое испытание Легенды: добудьте 5 чешуй молодого дракона.', 'reputation', 4, 4, NULL, NULL, NULL, 1, 0, '2026-07-16 11:22:21', '2026-07-17 05:59:41'),
(122, '[Орден] Подвиг: Истребитель властелинов', 'Второе испытание Легенды: уничтожьте 10 Властелинов Нежити.', 'reputation', 4, 4, NULL, 121, NULL, 1, 0, '2026-07-16 11:22:21', '2026-07-17 05:59:41'),
(123, '[Орден] Подвиг: Тёмная эссенция', 'Последнее испытание: вырвите тёмную эссенцию из Властелина Нежити.', 'reputation', 4, 4, NULL, 122, NULL, 1, 0, '2026-07-16 11:22:21', '2026-07-17 05:59:41'),
(125, 'Голова Крысиного Вожака', '1', 'main', 1, 1, NULL, NULL, NULL, 1, 0, '2026-07-25 18:38:49', '2026-07-25 22:41:30'),
(126, 'Крысиная напасть', 'Эйдран просит проредить крысиные стаи у входа в канализацию — их развелось слишком много.', 'one_time', 1, 1, NULL, NULL, NULL, 1, 0, '2026-07-26 10:52:24', '2026-07-26 10:52:24'),
(127, 'Плесневая зараза', 'Кроты и тараканы разносят по канализации странную плесень — Эйдран хочет разобраться, что это такое.', 'one_time', 1, 1, NULL, 126, NULL, 1, 0, '2026-07-26 10:52:24', '2026-07-26 10:52:24'),
(128, 'Ключ от решётки', 'Стражники нашли в глубине канализации старую рунную решётку — Эйдран просит расчистить путь к ней и получает от кузнеца ключ.', 'one_time', 1, 1, NULL, 127, NULL, 1, 0, '2026-07-26 10:52:24', '2026-07-26 10:52:24');
